import{_ as t,o,c as a,a7 as i}from"./chunks/framework.C4ZIv4ii.js";const p=JSON.parse('{"title":"AI Writing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai.md","filePath":"guide/ai.md","lastUpdated":1793206166000}'),r={name:"guide/ai.md"};function s(n,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-writing" tabindex="-1">AI Writing <a class="header-anchor" href="#ai-writing" aria-label="Permalink to &quot;AI Writing&quot;">​</a></h1><p><strong>Falcon AI</strong> writes with you in the post editor: a whole article from a short brief, better versions of a passage you select, and SEO titles, descriptions and alt text. It is free, comes with FalconCMS (on by default) and works with <strong>Claude</strong> (Anthropic), <strong>OpenAI</strong> or <strong>Google Gemini</strong>, using your own API key. You pay the provider for what you use; FalconCMS adds nothing. Gemini&#39;s Flash models have a free tier, so you can start without paying.</p><h2 id="set-it-up" tabindex="-1">Set it up <a class="header-anchor" href="#set-it-up" aria-label="Permalink to &quot;Set it up&quot;">​</a></h2><p>Open <strong>AI → Settings &amp; Usage</strong>.</p><ol><li>Under <strong>Provider</strong>, paste a key for one or more of them: <ul><li>Claude, from <a href="https://console.anthropic.com/settings/keys" target="_blank" rel="noreferrer">console.anthropic.com</a>. A Claude Pro subscription (claude.ai) does not include API credit: the API is paid separately.</li><li>OpenAI, from <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a>.</li><li>Gemini, from <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">Google AI Studio</a>, free, no card needed. New keys start with <code>AQ.</code> (older ones with <code>AIza</code>); copy the whole key. If Google refuses a new key, create another one in AI Studio.</li></ul></li><li>Choose the <strong>model</strong>. For Claude: Opus 5.5 gives the best writing, Sonnet 5.5 is faster at half the cost, Haiku 5.5 is the fastest and cheapest. For OpenAI and Gemini the list comes from your account, so new models appear as they are added. On Gemini&#39;s free tier choose a <strong>Flash</strong> model (a few requests a minute, about a thousand a day; Pro models need billing).</li><li>Choose which provider to <strong>write with</strong>. With several keys saved you can switch at any time.</li><li><strong>Save Changes</strong>, then <strong>Test</strong> beside the key. The test costs nothing.</li></ol><p>Keys are stored encrypted and never sent back to the browser: the field shows only their first and last characters. Saving the field unchanged keeps the key; <strong>Remove</strong> deletes it.</p><p>Also on this screen:</p><ul><li><strong>Language</strong> and <strong>Tone</strong>: the defaults for new articles (each article can choose its own). About 80 languages, from Bangla, English, Hindi and Arabic to Japanese, Swahili and Welsh, or &quot;the language of the topic&quot;. Type in the list to find one.</li><li><strong>Who can write with AI</strong>: administrators always can. Tick the other roles that may (Editor by default). Only users who can write posts or pages see the tools.</li><li><strong>Monthly limit</strong>: a ceiling on the tokens used each month (0 = no limit). When it is reached, AI writing stops until the next month. A medium article takes roughly 10,000–20,000 tokens.</li><li><strong>This month</strong>: requests and tokens, by provider, model and use. Only counts are kept, never the text.</li></ul><h2 id="write-an-article" tabindex="-1">Write an article <a class="header-anchor" href="#write-an-article" aria-label="Permalink to &quot;Write an article&quot;">​</a></h2><p>In the post editor, <strong>✨ Write with AI</strong> sits beside the Rich Editor and Page Builder tabs.</p><ol><li><strong>Brief</strong>: the topic, and optionally the focus keyword, the audience, language, tone, length (short, medium or long) and notes (&quot;mention our Dhaka shop&quot;, &quot;no prices&quot;).</li><li><strong>Outline</strong>: a title and the sections, each with the points it will cover. Change any heading or point, reorder sections, add or remove them, or ask for a new outline.</li><li><strong>Write the article</strong>: each section is written in turn and appears as it is written. <strong>Stop</strong> at any time; <strong>Continue</strong> picks up where it stopped.</li><li><strong>Put it in the editor</strong>: replace what is there, or add the article after it, and optionally use the title. Then the SEO title, meta description, excerpt and tags are written too; fields that already have text are left alone.</li></ol><p>Nothing is saved until you save the post. The article goes into the Rich Editor; with the Page Builder open, switch to the Rich Editor first. <strong>Read it through before you publish</strong>: AI can get facts wrong, and search engines reward pages written for people.</p><h2 id="improve-a-passage" tabindex="-1">Improve a passage <a class="header-anchor" href="#improve-a-passage" aria-label="Permalink to &quot;Improve a passage&quot;">​</a></h2><p>Select text in the Rich Editor, then <strong>Improve selection</strong>: rewrite, expand, shorten, simplify, translate to English, or translate to Bangla. The selection is replaced; <strong>Ctrl+Z</strong> puts it back.</p><h2 id="seo-suggestions" tabindex="-1">SEO suggestions <a class="header-anchor" href="#seo-suggestions" aria-label="Permalink to &quot;SEO suggestions&quot;">​</a></h2><p>With <a href="/falconcms/guide/seo.html">Falcon SEO</a>, <strong>✨ Suggest with AI</strong> appears beside the SEO title and meta description in the editor&#39;s SEO box (and in its Analysis tab for a weak one): three options for the page and its focus keyword, each with the reason. Site Analysis&#39;s AI fixes (Pro) use it as well.</p><h2 id="privacy-and-security" tabindex="-1">Privacy and security <a class="header-anchor" href="#privacy-and-security" aria-label="Permalink to &quot;Privacy and security&quot;">​</a></h2><ul><li>Only the text being worked on is sent to the provider, when someone asks for it.</li><li>Everything the AI writes is cleaned before it reaches the editor: scripts, styles, frames, event attributes and unsafe links are removed, so a reply cannot run code in the admin.</li><li>Each request is checked twice (the admin&#39;s access rules and the request itself), limited per minute, and held to fixed sizes.</li></ul><h2 id="for-developers" tabindex="-1">For developers <a class="header-anchor" href="#for-developers" aria-label="Permalink to &quot;For developers&quot;">​</a></h2><ul><li><code>falcon_ai_providers</code> (filter): <code>array&lt;string, class-string&gt;</code> — add a provider class implementing <code>FalconAi\\Contracts\\AiProvider</code>.</li><li><code>falcon_ai_generated</code> (action): <code>string $feature, AiResult $result</code> — after every answer.</li><li><code>app(FalconAi\\Support\\AiManager::class)-&gt;json(...)</code> / <code>-&gt;stream(...)</code> — ask the chosen provider from your own code; the monthly limit and the usage record apply.</li></ul>',20)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
